// The wiki's search index, generated by plugins/wiki.ts from every page listed in wiki/nav.json.
declare module 'virtual:wiki-index' {
  export interface WikiIndexPage {
    /** address */ u: string;
    /** title */ t: string;
    /** group title */ g: string;
    /** group colour */ c: string;
    /** summary from nav.json */ s: string;
    /** the page's lead paragraph */ l: string;
    /** sections: id, heading, first words */ h: { id: string; t: string; x: string }[];
  }
  const index: WikiIndexPage[];
  export default index;
}

declare module 'virtual:wiki-passages' {
  const corpus: import('../src/wiki/assistant-context').Corpus;
  export default corpus;
}
